#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int mn(int a, int b)  {
    return a < b ? a : b;
}
int mx(int a, int b)  {
    return a > b ? a : b;
}
int read(void)  {
    int x = 0;
    if (scanf("%d", &x) != 1) return 0;
    return x;
}
int readstr(int* a)  {
    char s[20001];
    if (scanf("%20000s", s) != 1) return 0;
    if (strcmp(s, "-") == 0) return 0;
    int n = (int)strlen(s);
    for (int i = 0; i < n; i++) a[i] = (unsigned char)s[i];
    return n;
}
void emit(int x)  {
    printf("%d ", x);
}
void emitstr(int* a, int n)  {
    if (n == 0) putchar('-');
    for (int i = 0; i < n; i++) putchar(a[i]);
    putchar(' ');
}
int main(void)  {
    static int a[20000];
    static int b[20000];
    static int d[20000];
    static int e[20000];
    int bottom = 0, cols = 0, i = 0, j = 0, left = 0, right = 0, rows = 0, top = 0;
    // 按行读入一维 a，坐标 (i,j) 映射为 i*cols+j。
    rows = read();
    cols = read();
    for (i = 0; i < (rows * cols); i += 1)  {
        a[i] = read();
    }
    top = 0;
    bottom = (rows - 1);
    left = 0;
    right = (cols - 1);
    // 四边界围住的矩形恰好是未访问区域，每走完一边就向内收缩。
    while ((top <= bottom) && (left <= right))  {
        for (j = left; j < (right + 1); j += 1)  {
            // 顶行从左向右输出；随后移动 top，右列不会重复右上角。
            emit(a[((top * cols) + j)]);
        }
        top = (top + 1);
        for (i = top; i < (bottom + 1); i += 1)  {
            emit(a[((i * cols) + right)]);
        }
        right = (right - 1);
        // 剩余单行可能已在顶边输出，必须确认底行仍存在。
        if (top <= bottom)  {
            for (j = right; j > (left - 1); j += -1)  {
                emit(a[((bottom * cols) + j)]);
            }
            bottom = (bottom - 1);
        }
        if (left <= right)  {
            for (i = bottom; i > (top - 1); i += -1)  {
                emit(a[((i * cols) + left)]);
            }
            left = (left + 1);
        }
    }
    return 0;
}

