import sys

_tokens = iter(sys.stdin.read().split())


def read():
    return int(next(_tokens))


def readstr(a):
    s = next(_tokens)
    if s == "-":
        return 0
    for i, c in enumerate(s):
        a[i] = ord(c)
    return len(s)


def emit(x):
    print(x, end=" ")


def emitstr(a, n):
    print("".join(chr(x) for x in a[:n]) if n else "-", end=" ")


def mn(a, b):
    return min(a, b)


def mx(a, b):
    return max(a, b)


a = [0] * 20000
b = [0] * 20000
d = [0] * 20000
e = [0] * 20000
