cols = read()
for i in range((rows * cols)):
    a[i] = read()
top = 0
bottom = rows - 1
left = 0
right = cols - 1
# 四边界围住的矩形恰好是未访问区域，每走完一边就向内收缩。
while (top <= bottom) and (left <= right):
    for j in range(left, (right + 1)):
        # 顶行从左向右输出；随后移动 top，右列不会重复右上角。
        emit(a[((top * cols) + j)])
    top = top + 1
    for i in range(top, (bottom + 1)):
        emit(a[((i * cols) + right)])
    right = right - 1
    # 剩余单行可能已在顶边输出，必须确认底行仍存在。
    if top <= bottom:
